import type { ReactNode } from 'react'
import { CircleAlert, RotateCcw } from 'lucide-react'

import { cx } from '~/lib/cx'
import { Button } from './button'
import styles from './error-state.module.scss'

export interface ErrorStateProps {
  title?: ReactNode
  description?: ReactNode
  onRetry?: () => void
  retryLabel?: string
  className?: string
  children?: ReactNode
}

export function ErrorState({
  title = 'Something went wrong',
  description = 'The section could not be loaded. Try again.',
  onRetry,
  retryLabel = 'Try again',
  className,
  children,
}: ErrorStateProps) {
  return (
    <div role="alert" className={cx(styles.root, className)}>
      <span className={styles.icon}>
        <CircleAlert aria-hidden />
      </span>
      <div className={styles.copy}>
        <p className={styles.title}>{title}</p>
        <p className={styles.description}>{description}</p>
      </div>
      {children}
      {onRetry ? (
        <Button variant="outline" size="sm" onClick={onRetry}>
          <RotateCcw aria-hidden />
          {retryLabel}
        </Button>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: vz.space(3);
  padding: vz.space(10) vz.space(6);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('2xl');
  background: vz.color('card');
  text-align: center;
}

.icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: vz.space(10);
  height: vz.space(10);
  border-radius: vz.radius('full');
  background: vz.color('destructive', 0.1);
  color: vz.color('destructive');

  svg {
    @include vz.icon(5);
  }
}

.copy {
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.description {
  max-width: 24rem;
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.5;
}
